from itertools import permutations

names = ["Kammer", "Lugo", "Trillo", "Waite", "Yoshida", "Zinn"]
recorded = {"Kammer", "Lugo"}
claimed = "A"

def positions(order):
    return {name: i + 1 for i, name in enumerate(order)}

def valid(p):
    rec_pos = {p[n] for n in recorded}
    if 4 in rec_pos:                       # fourth audition cannot be recorded
        return False
    if 5 not in rec_pos:                   # fifth audition must be recorded
        return False
    if not (p["Waite"] < p["Kammer"] and p["Waite"] < p["Lugo"]):
        return False                       # Waite before both recorded auditions
    if not p["Kammer"] < p["Trillo"]:      # Kammer before Trillo
        return False
    if not p["Zinn"] < p["Yoshida"]:       # Zinn before Yoshida
        return False
    return True

def consistent(p):
    # Given condition: Kammer immediately before Yoshida
    return valid(p) and p["Yoshida"] == p["Kammer"] + 1

# Exhaustive enumeration of all 720 orderings (complete, not sampled)
schedules = []
for order in permutations(names):
    p = positions(order)
    if consistent(p):
        schedules.append(p)

print("total orderings checked: 720")
print("consistent schedules:", len(schedules))
for p in schedules:
    print([name for name, _ in sorted(p.items(), key=lambda x: x[1])])

if not schedules:
    print("UNSUPPORTED: no consistent schedule found")
else:
    options = {
        "A": lambda p: p["Kammer"] == 2,
        "B": lambda p: p["Trillo"] == 4,
        "C": lambda p: p["Waite"] == 3,
        "D": lambda p: p["Yoshida"] == 6,
        "E": lambda p: p["Zinn"] == 2,
    }
    possible = {}
    for label, pred in options.items():
        possible[label] = any(pred(p) for p in schedules)
        print(label, "possible" if possible[label] else "impossible")

    print("claimed answer:", claimed, "possible:", possible[claimed])
    print("CHECK PASS" if possible[claimed] else "CHECK FAIL")
